package org.mercury.rest.server.actions;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.beans.factory.annotation.Qualifier;
import org.springframework.stereotype.Service;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.node.ArrayNode;
import com.fasterxml.jackson.databind.node.ObjectNode;

import pro.ibpm.mercury.business.MCaseBusiness;
import pro.ibpm.mercury.context.Context;
import pro.ibpm.mercury.dao.helpers.TypeCaseHelper;
import pro.ibpm.mercury.entities.attr.TypeCase;
import pro.ibpm.mercury.entities.attr.TypeCode;
import pro.ibpm.mercury.exceptions.MercuryException;
import pro.ibpm.mercury.exceptions.SQLNoDataFoundException;
import pro.ibpm.mercury.logic.api.attr.ITypeCaseLogic;
import pro.ibpm.mercury.logic.api.attr.ITypeCodeLogic;

/**
 * Pobranie typu sprawy i zbudowanie jego specyfikacji OpenAPI ({@link CaseTypeOpenApi}) oraz lista kodów typów i ich
 * wersji dla strony wyboru typu. Typy są czytane w jednej transakcji tylko do odczytu, bo lista parametrów
 * (<code>typeParams</code>) jest ładowana leniwie.
 */
@Service
public class CaseTypeOpenApiService {

	private static final Logger logger = LoggerFactory.getLogger(CaseTypeOpenApiService.class);
	private static final ObjectMapper MAPPER = new ObjectMapper();

	@Autowired
	private ITypeCaseLogic typeCaseLogic;

	@Autowired
	private ITypeCodeLogic typeCodeLogic;

	/** Menedżer transakcji danych spraw i typów (definicja w <code>dao-context.xml</code>) */
	@Autowired
	@Qualifier("transactionManagerDefault")
	private PlatformTransactionManager transactionManager;

	/**
	 * @param context
	 *            kontekst użytkownika; <code>maxDepthResult</code> ogranicza zagnieżdżenie spraw zależnych
	 * @param typeCode
	 *            kod typu sprawy
	 * @return specyfikacja ostatniej wersji typu albo <code>null</code>, gdy typ o tym kodzie nie istnieje
	 */
	public ObjectNode buildLatest(Context context, String typeCode) throws MercuryException {
		return buildVersion(context, typeCode, null, null);
	}

	/**
	 * @param context
	 *            kontekst użytkownika; <code>maxDepthResult</code> ogranicza zagnieżdżenie spraw zależnych
	 * @param typeCode
	 *            kod typu sprawy
	 * @param version
	 *            wersja w postaci <code>3.1</code> (samo <code>3</code> to <code>3.0</code>) albo {@code null}
	 * @param typeId
	 *            identyfikator wersji typu (<code>TypeCase.id</code>, np. z nagłówka sprawy) albo {@code null}
	 * @return specyfikacja wskazanej wersji typu (bez wskazania: ostatniej) albo <code>null</code>, gdy typu albo wersji
	 *         nie ma
	 */
	public ObjectNode buildVersion(Context context, String typeCode, String version, Long typeId)
			throws MercuryException {
		return inTransaction(() -> buildInTransaction(context, typeCode, version, typeId));
	}

	/**
	 * @return kody typów spraw (nie dokumentów) jako tablica obiektów <code>{code, label, alias}</code> posortowana po
	 *         kodzie
	 */
	public ArrayNode listCodes(Context context) throws MercuryException {
		List<TypeCode> codes = new ArrayList<>(typeCodeLogic.findAllCaseTypeCodes(context));
		codes.sort(Comparator.comparing(c -> c.getName() == null ? "" : c.getName().toLowerCase()));
		ArrayNode result = MAPPER.createArrayNode();
		for (TypeCode code : codes) {
			ObjectNode item = result.addObject();
			item.put("code", code.getName());
			putIfNotBlank(item, "label", code.getLabel());
			putIfNotBlank(item, "alias", code.getAlias());
		}
		return result;
	}

	/**
	 * @return wersje typu o podanym kodzie (najnowsza pierwsza) jako tablica obiektów
	 *         <code>{typeId, version, latest, active}</code> albo {@code null}, gdy kod nie ma typów
	 */
	public ArrayNode listVersions(Context context, String typeCode) throws MercuryException {
		List<TypeCase> versions = loadVersions(context, typeCode);
		if (versions.isEmpty()) {
			return null;
		}
		ArrayNode result = MAPPER.createArrayNode();
		for (TypeCase type : versions) {
			ObjectNode item = result.addObject();
			item.put("typeId", type.getId());
			item.put("version", CaseTypeOpenApi.versionOf(type));
			item.put("latest", Boolean.TRUE.equals(type.getIsLatestVersion()));
			item.put("active", Boolean.TRUE.equals(type.getIsActive()));
		}
		return result;
	}

	/**
	 * Wybór wersji typu z listy.
	 *
	 * @param versions
	 *            wersje typu o jednym kodzie
	 * @param version
	 *            wersja <code>3.1</code> albo {@code null}
	 * @param typeId
	 *            identyfikator wersji albo {@code null}. Ma pierwszeństwo przed {@code version}
	 * @return wskazana wersja, ostatnia (<code>isLatestVersion</code>), gdy nic nie wskazano, albo {@code null}
	 */
	static TypeCase select(List<TypeCase> versions, String version, Long typeId) {
		if (typeId != null) {
			return versions.stream().filter(t -> typeId.equals(t.getId())).findFirst().orElse(null);
		}
		if (version != null && !version.trim().isEmpty()) {
			String wanted = normalizeVersion(version);
			return versions.stream().filter(t -> CaseTypeOpenApi.versionOf(t).equals(wanted)).findFirst().orElse(null);
		}
		return versions.stream().filter(t -> Boolean.TRUE.equals(t.getIsLatestVersion())).findFirst()
				.orElse(versions.isEmpty() ? null : versions.get(0));
	}

	/** @return wersja w postaci <code>głowna.poboczna</code>: <code>3</code> to <code>3.0</code> */
	static String normalizeVersion(String version) {
		String trimmed = version.trim();
		return trimmed.indexOf('.') < 0 ? trimmed + ".0" : trimmed;
	}

	private ObjectNode buildInTransaction(Context context, String typeCode, String version, Long typeId)
			throws MercuryException {
		TypeCase typeCase;
		if (version == null && typeId == null) {
			typeCase = loadLatest(context, typeCode);
		} else {
			typeCase = select(loadVersions(context, typeCode), version, typeId);
			if (typeCase != null) {
				typeCase = TypeCaseHelper.forceInitalizeType(typeCase, logger);
			}
		}
		if (typeCase == null) {
			logger.debug("--> buildVersion: brak typu o kodzie {} (wersja {}, typeId {})", typeCode, version, typeId);
			return null;
		}
		Integer depth = context.getMaxDepthResult();
		int maxDepth = depth != null ? depth : MCaseBusiness.MAX_DEPTH;
		return CaseTypeOpenApi.build(typeCase, code -> {
			try {
				return loadLatest(context, code);
			} catch (MercuryException e) {
				/* typ zależny niedostępny: pole zostaje bez odwołania $ref */
				logger.warn("--> buildVersion: nie udało się pobrać typu zależnego {}: {}", code, e.getMessage());
				return null;
			}
		}, maxDepth);
	}

	private List<TypeCase> loadVersions(Context context, String typeCode) throws MercuryException {
		try {
			List<TypeCase> versions = typeCaseLogic.findAllVersionByTypeCode(context, typeCode);
			return versions == null ? new ArrayList<>() : versions;
		} catch (SQLNoDataFoundException e) {
			/* logika zgłasza brak typu wyjątkiem */
			return new ArrayList<>();
		}
	}

	private TypeCase loadLatest(Context context, String typeCode) throws MercuryException {
		TypeCase typeCase;
		try {
			typeCase = typeCaseLogic.findLastVersionByTypeCode(context, typeCode);
		} catch (SQLNoDataFoundException e) {
			/* logika zgłasza brak typu wyjątkiem */
			return null;
		}
		return typeCase == null ? null : TypeCaseHelper.forceInitalizeType(typeCase, logger);
	}

	private static void putIfNotBlank(ObjectNode node, String name, String value) {
		if (value != null && !value.trim().isEmpty()) {
			node.put(name, value);
		}
	}

	/** Wywołanie w transakcji tylko do odczytu */
	private <T> T inTransaction(MercuryCallable<T> callable) throws MercuryException {
		/*
		 * Transakcja programowa, a nie @Transactional: ta klasa jest skanowana w kontekście serwletu, w którym
		 * adnotacje transakcyjne nie są włączone, więc leniwa lista typeParams nie miałaby sesji.
		 */
		TransactionTemplate template = new TransactionTemplate(transactionManager);
		template.setReadOnly(true);
		try {
			return template.execute(status -> {
				try {
					return callable.call();
				} catch (MercuryException e) {
					throw new MercuryRuntimeWrapper(e);
				}
			});
		} catch (MercuryRuntimeWrapper e) {
			throw e.getMercuryException();
		}
	}

	@FunctionalInterface
	private interface MercuryCallable<T> {
		T call() throws MercuryException;
	}

	/** Opakowanie wyjątku sprawy na czas przejścia przez wywołanie zwrotne transakcji */
	private static final class MercuryRuntimeWrapper extends RuntimeException {
		private static final long serialVersionUID = 1L;
		private final transient MercuryException cause;

		MercuryRuntimeWrapper(MercuryException cause) {
			super(cause);
			this.cause = cause;
		}

		MercuryException getMercuryException() {
			return cause;
		}
	}
}

package org.mercury.rest.server.actions;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.beans.factory.annotation.Qualifier;
import org.springframework.stereotype.Service;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.node.ArrayNode;
import com.fasterxml.jackson.databind.node.ObjectNode;

import pro.ibpm.mercury.business.MCaseBusiness;
import pro.ibpm.mercury.context.Context;
import pro.ibpm.mercury.dao.helpers.TypeCaseHelper;
import pro.ibpm.mercury.entities.attr.TypeCase;
import pro.ibpm.mercury.entities.attr.TypeCode;
import pro.ibpm.mercury.exceptions.MercuryException;
import pro.ibpm.mercury.exceptions.SQLNoDataFoundException;
import pro.ibpm.mercury.logic.api.attr.ITypeCaseLogic;
import pro.ibpm.mercury.logic.api.attr.ITypeCodeLogic;

/**
 * Pobranie typu sprawy i zbudowanie jego specyfikacji OpenAPI ({@link CaseTypeOpenApi}) oraz lista kodów typów i ich
 * wersji dla strony wyboru typu. Typy są czytane w jednej transakcji tylko do odczytu, bo lista parametrów
 * (<code>typeParams</code>) jest ładowana leniwie.
 */
@Service
public class CaseTypeOpenApiService {

	private static final Logger logger = LoggerFactory.getLogger(CaseTypeOpenApiService.class);
	private static final ObjectMapper MAPPER = new ObjectMapper();

	@Autowired
	private ITypeCaseLogic typeCaseLogic;

	@Autowired
	private ITypeCodeLogic typeCodeLogic;

	/** Menedżer transakcji danych spraw i typów (definicja w <code>dao-context.xml</code>) */
	@Autowired
	@Qualifier("transactionManagerDefault")
	private PlatformTransactionManager transactionManager;

	/**
	 * @param context
	 *            kontekst użytkownika; <code>maxDepthResult</code> ogranicza zagnieżdżenie spraw zależnych
	 * @param typeCode
	 *            kod typu sprawy
	 * @return specyfikacja ostatniej wersji typu albo <code>null</code>, gdy typ o tym kodzie nie istnieje
	 */
	public ObjectNode buildLatest(Context context, String typeCode) throws MercuryException {
		return buildVersion(context, typeCode, null, null);
	}

	/**
	 * @param context
	 *            kontekst użytkownika; <code>maxDepthResult</code> ogranicza zagnieżdżenie spraw zależnych
	 * @param typeCode
	 *            kod typu sprawy
	 * @param version
	 *            wersja w postaci <code>3.1</code> (samo <code>3</code> to <code>3.0</code>) albo {@code null}
	 * @param typeId
	 *            identyfikator wersji typu (<code>TypeCase.id</code>, np. z nagłówka sprawy) albo {@code null}
	 * @return specyfikacja wskazanej wersji typu (bez wskazania: ostatniej) albo <code>null</code>, gdy typu albo wersji
	 *         nie ma
	 */
	public ObjectNode buildVersion(Context context, String typeCode, String version, Long typeId)
			throws MercuryException {
		return inTransaction(() -> buildInTransaction(context, typeCode, version, typeId));
	}

	/**
	 * @return kody typów spraw (nie dokumentów) jako tablica obiektów <code>{code, label, alias}</code> posortowana po
	 *         kodzie
	 */
	public ArrayNode listCodes(Context context) throws MercuryException {
		List<TypeCode> codes = new ArrayList<>(typeCodeLogic.findAllCaseTypeCodes(context));
		codes.sort(Comparator.comparing(c -> c.getName() == null ? "" : c.getName().toLowerCase()));
		ArrayNode result = MAPPER.createArrayNode();
		for (TypeCode code : codes) {
			ObjectNode item = result.addObject();
			item.put("code", code.getName());
			putIfNotBlank(item, "label", code.getLabel());
			putIfNotBlank(item, "alias", code.getAlias());
		}
		return result;
	}

	/**
	 * @return wersje typu o podanym kodzie (najnowsza pierwsza) jako tablica obiektów
	 *         <code>{typeId, version, latest, active}</code> albo {@code null}, gdy kod nie ma typów
	 */
	public ArrayNode listVersions(Context context, String typeCode) throws MercuryException {
		List<TypeCase> versions = loadVersions(context, typeCode);
		if (versions.isEmpty()) {
			return null;
		}
		ArrayNode result = MAPPER.createArrayNode();
		for (TypeCase type : versions) {
			ObjectNode item = result.addObject();
			item.put("typeId", type.getId());
			item.put("version", CaseTypeOpenApi.versionOf(type));
			item.put("latest", Boolean.TRUE.equals(type.getIsLatestVersion()));
			item.put("active", Boolean.TRUE.equals(type.getIsActive()));
		}
		return result;
	}

	/**
	 * Wybór wersji typu z listy.
	 *
	 * @param versions
	 *            wersje typu o jednym kodzie
	 * @param version
	 *            wersja <code>3.1</code> albo {@code null}
	 * @param typeId
	 *            identyfikator wersji albo {@code null}. Ma pierwszeństwo przed {@code version}
	 * @return wskazana wersja, ostatnia (<code>isLatestVersion</code>), gdy nic nie wskazano, albo {@code null}
	 */
	static TypeCase select(List<TypeCase> versions, String version, Long typeId) {
		if (typeId != null) {
			return versions.stream().filter(t -> typeId.equals(t.getId())).findFirst().orElse(null);
		}
		if (version != null && !version.trim().isEmpty()) {
			String wanted = normalizeVersion(version);
			return versions.stream().filter(t -> CaseTypeOpenApi.versionOf(t).equals(wanted)).findFirst().orElse(null);
		}
		return versions.stream().filter(t -> Boolean.TRUE.equals(t.getIsLatestVersion())).findFirst()
				.orElse(versions.isEmpty() ? null : versions.get(0));
	}

	/** @return wersja w postaci <code>głowna.poboczna</code>: <code>3</code> to <code>3.0</code> */
	static String normalizeVersion(String version) {
		String trimmed = version.trim();
		return trimmed.indexOf('.') < 0 ? trimmed + ".0" : trimmed;
	}

	private ObjectNode buildInTransaction(Context context, String typeCode, String version, Long typeId)
			throws MercuryException {
		boolean selectedVersion = version != null || typeId != null;
		TypeCase typeCase;
		if (!selectedVersion) {
			typeCase = loadLatest(context, typeCode);
		} else {
			typeCase = select(loadVersions(context, typeCode), version, typeId);
			if (typeCase != null) {
				typeCase = TypeCaseHelper.forceInitalizeType(typeCase, logger);
			}
		}
		if (typeCase == null) {
			logger.debug("--> buildVersion: brak typu o kodzie {} (wersja {}, typeId {})", typeCode, version, typeId);
			return null;
		}
		final TypeCase selectedType = typeCase;
		Integer depth = context.getMaxDepthResult();
		int maxDepth = depth != null ? depth : MCaseBusiness.MAX_DEPTH;
		return CaseTypeOpenApi.build(selectedType,
				code -> loadSubTypeForSpec(context, selectedType, selectedVersion, code), maxDepth);
	}

	private TypeCase loadSubTypeForSpec(Context context, TypeCase rootType, boolean selectedVersion, String subTypeCode) {
		try {
			return selectedVersion ? loadHistorical(context, subTypeCode, rootType) : loadLatest(context, subTypeCode);
		} catch (Exception e) {
			/* typ zależny niedostępny: pole zostaje bez odwołania $ref */
			logger.warn("--> buildVersion: nie udało się pobrać typu zależnego {}: {}", subTypeCode, e.getMessage());
			return null;
		}
	}

	/**
	 * W trybie specyfikacji historycznej (`?v=`/`?typeId=`) typ zależny jest wybierany tylko z dokładnie tej samej
	 * wersji (`version.versionMinor`) co typ główny. Brak dopasowania oznacza brak schematu zależnego (`$ref`).
	 */
	private TypeCase loadHistorical(Context context, String typeCode, TypeCase rootType) throws MercuryException {
		TypeCase selected = selectHistorical(loadVersions(context, typeCode), rootType);
		return selected == null ? null : TypeCaseHelper.forceInitalizeType(selected, logger);
	}

	/**
	 * Wybór wersji typu zależnego dla specyfikacji historycznej.
	 */
	static TypeCase selectHistorical(List<TypeCase> versions, TypeCase rootType) {
		if (versions == null || versions.isEmpty() || rootType == null) {
			return null;
		}
		String wanted = versionOf(rootType);
		for (TypeCase type : versions) {
			if (wanted.equals(versionOf(type))) {
				return type;
			}
		}
		return null;
	}

	private static String versionOf(TypeCase type) {
		return CaseTypeOpenApi.versionOf(type);
	}

	private List<TypeCase> loadVersions(Context context, String typeCode) throws MercuryException {
		try {
			List<TypeCase> versions = typeCaseLogic.findAllVersionByTypeCode(context, typeCode);
			return versions == null ? new ArrayList<>() : versions;
		} catch (SQLNoDataFoundException e) {
			/* logika zgłasza brak typu wyjątkiem */
			return new ArrayList<>();
		}
	}

	private TypeCase loadLatest(Context context, String typeCode) throws MercuryException {
		TypeCase typeCase;
		try {
			typeCase = typeCaseLogic.findLastVersionByTypeCode(context, typeCode);
		} catch (SQLNoDataFoundException e) {
			/* logika zgłasza brak typu wyjątkiem */
			return null;
		}
		return typeCase == null ? null : TypeCaseHelper.forceInitalizeType(typeCase, logger);
	}

	private static void putIfNotBlank(ObjectNode node, String name, String value) {
		if (value != null && !value.trim().isEmpty()) {
			node.put(name, value);
		}
	}

	/** Wywołanie w transakcji tylko do odczytu */
	private <T> T inTransaction(MercuryCallable<T> callable) throws MercuryException {
		/*
		 * Transakcja programowa, a nie @Transactional: ta klasa jest skanowana w kontekście serwletu, w którym
		 * adnotacje transakcyjne nie są włączone, więc leniwa lista typeParams nie miałaby sesji.
		 */
		TransactionTemplate template = new TransactionTemplate(transactionManager);
		template.setReadOnly(true);
		try {
			return template.execute(status -> {
				try {
					return callable.call();
				} catch (MercuryException e) {
					throw new MercuryRuntimeWrapper(e);
				}
			});
		} catch (MercuryRuntimeWrapper e) {
			throw e.getMercuryException();
		}
	}

	@FunctionalInterface
	private interface MercuryCallable<T> {
		T call() throws MercuryException;
	}

	/** Opakowanie wyjątku sprawy na czas przejścia przez wywołanie zwrotne transakcji */
	private static final class MercuryRuntimeWrapper extends RuntimeException {
		private static final long serialVersionUID = 1L;
		private final transient MercuryException cause;

		MercuryRuntimeWrapper(MercuryException cause) {
			super(cause);
			this.cause = cause;
		}

		MercuryException getMercuryException() {
			return cause;
		}
	}
}

package org.mercury.rest.server.actions;

import java.util.Arrays;
import java.util.List;

import junit.framework.TestCase;
import pro.ibpm.mercury.entities.attr.TypeCase;

/**
 * Testy wyboru wersji typu do specyfikacji (zadanie 133, etap 2): <code>?v=3.1</code> i <code>?typeId=</code>.
 */
public class CaseTypeVersionSelectTest extends TestCase {

	private static TypeCase version(long id, long main, double minor, boolean latest) {
		TypeCase type = new TypeCase();
		type.setId(id);
		type.setVersion(main);
		type.setVersionMinor(minor);
		type.setIsLatestVersion(latest);
		return type;
	}

	private final List<TypeCase> versions = Arrays.asList(version(30, 3, 1, true), version(20, 3, 0, false),
			version(10, 2, 0, false));

	public void testNoSelectorGivesLatest() {
		assertEquals(Long.valueOf(30), CaseTypeOpenApiService.select(versions, null, null).getId());
		assertEquals(Long.valueOf(30), CaseTypeOpenApiService.select(versions, " ", null).getId());
	}

	public void testMainAndMinorVersion() {
		assertEquals(Long.valueOf(30), CaseTypeOpenApiService.select(versions, "3.1", null).getId());
		assertEquals(Long.valueOf(20), CaseTypeOpenApiService.select(versions, "3.0", null).getId());
	}

	public void testPlainMainVersionMeansMinorZero() {
		assertEquals(Long.valueOf(20), CaseTypeOpenApiService.select(versions, "3", null).getId());
		assertEquals(Long.valueOf(10), CaseTypeOpenApiService.select(versions, "2", null).getId());
	}

	public void testTypeIdWinsOverVersion() {
		assertEquals(Long.valueOf(10), CaseTypeOpenApiService.select(versions, "3.1", 10L).getId());
	}

	public void testUnknownVersionOrTypeIdGivesNull() {
		assertNull(CaseTypeOpenApiService.select(versions, "9.9", null));
		assertNull(CaseTypeOpenApiService.select(versions, null, 999L));
	}

	public void testNormalizeVersion() {
		assertEquals("3.0", CaseTypeOpenApiService.normalizeVersion("3"));
		assertEquals("3.1", CaseTypeOpenApiService.normalizeVersion(" 3.1 "));
	}
}

package org.mercury.rest.server.actions;

import java.util.Arrays;
import java.util.List;

import junit.framework.TestCase;
import pro.ibpm.mercury.entities.attr.TypeCase;

/**
 * Testy wyboru wersji typu do specyfikacji (zadanie 133, etap 2): <code>?v=3.1</code> i <code>?typeId=</code>.
 */
public class CaseTypeVersionSelectTest extends TestCase {

	private static TypeCase version(long id, long main, double minor, boolean latest) {
		TypeCase type = new TypeCase();
		type.setId(id);
		type.setVersion(main);
		type.setVersionMinor(minor);
		type.setIsLatestVersion(latest);
		return type;
	}

	private final List<TypeCase> versions = Arrays.asList(version(30, 3, 1, true), version(20, 3, 0, false),
			version(10, 2, 0, false));

	public void testNoSelectorGivesLatest() {
		assertEquals(Long.valueOf(30), CaseTypeOpenApiService.select(versions, null, null).getId());
		assertEquals(Long.valueOf(30), CaseTypeOpenApiService.select(versions, " ", null).getId());
	}

	public void testMainAndMinorVersion() {
		assertEquals(Long.valueOf(30), CaseTypeOpenApiService.select(versions, "3.1", null).getId());
		assertEquals(Long.valueOf(20), CaseTypeOpenApiService.select(versions, "3.0", null).getId());
	}

	public void testPlainMainVersionMeansMinorZero() {
		assertEquals(Long.valueOf(20), CaseTypeOpenApiService.select(versions, "3", null).getId());
		assertEquals(Long.valueOf(10), CaseTypeOpenApiService.select(versions, "2", null).getId());
	}

	public void testTypeIdWinsOverVersion() {
		assertEquals(Long.valueOf(10), CaseTypeOpenApiService.select(versions, "3.1", 10L).getId());
	}

	public void testUnknownVersionOrTypeIdGivesNull() {
		assertNull(CaseTypeOpenApiService.select(versions, "9.9", null));
		assertNull(CaseTypeOpenApiService.select(versions, null, 999L));
	}

	public void testNormalizeVersion() {
		assertEquals("3.0", CaseTypeOpenApiService.normalizeVersion("3"));
		assertEquals("3.1", CaseTypeOpenApiService.normalizeVersion(" 3.1 "));
	}

	public void testHistoricalSubTypePicksExactVersionFirst() {
		TypeCase root = version(100, 3, 1, true);
		TypeCase selected = CaseTypeOpenApiService.selectHistorical(versions, root);
		assertNotNull(selected);
		assertEquals(Long.valueOf(30), selected.getId());
	}

	public void testHistoricalSubTypeRequiresExactVersion() {
		TypeCase root = version(101, 3, 2, true);
		assertNull(CaseTypeOpenApiService.selectHistorical(versions, root));

		TypeCase rootOld = version(102, 2, 5, true);
		assertNull(CaseTypeOpenApiService.selectHistorical(versions, rootOld));
	}

	public void testHistoricalSubTypeReturnsNullWhenOnlyNewerVersionsExist() {
		TypeCase root = version(103, 1, 0, true);
		assertNull(CaseTypeOpenApiService.selectHistorical(versions, root));
	}
}
